class TestConcurrency:
    """Validate behavior under concurrent execution."""

    def test_concurrent_executions(self, isolated_workspace, sample_coverage_data):
        """Multiple concurrent executions must not interfere."""
        tmp_path, artifacts_dir = isolated_workspace
        (artifacts_dir / "coverage.json").write_text(json.dumps(sample_coverage_data))

        import concurrent.futures
        import threading

        outputs = []
        lock = threading.Lock()

        def run_instance(i):
            output_path = tmp_path / f"report_{i}.json"
            result = run_script([str(artifacts_dir), str(output_path)])
            with lock:
                outputs.append((i, result.returncode, output_path))
            return result.returncode

        with concurrent.futures.ThreadPoolExecutor(max_workers=5) as executor:
            futures = [executor.submit(run_instance, i) for i in range(5)]
            results = [f.result() for f in futures]

        assert all(rc == 0 for rc in results)
        assert len(outputs) == 5

        # Verify all outputs are valid and identical
        reports = []
        for _, _, path in outputs:
            assert path.exists()
            reports.append(json.loads(path.read_text()))

        for report in reports[1:]:
            assert report["totals"] == reports[0]["totals"]


