class TestPropertyBased:
    """Validate mathematical properties of aggregation."""

    def test_aggregation_commutative(self, isolated_workspace, sample_coverage_data):
        """Order of file processing must not affect results."""
        tmp_path, artifacts_dir = isolated_workspace

        # Create files with different data
        data_a = {"total": {"statements": {"total": 10, "covered": 5},
                            "branches": {"total": 5, "covered": 2},
                            "functions": {"total": 3, "covered": 1}}}
        data_b = {"total": {"statements": {"total": 20, "covered": 15},
                            "branches": {"total": 10, "covered": 8},
                            "functions": {"total": 5, "covered": 4}}}

        (artifacts_dir / "a.json").write_text(json.dumps(data_a))
        (artifacts_dir / "b.json").write_text(json.dumps(data_b))

        result = run_script([str(artifacts_dir), str(tmp_path / "report.json")])
        assert result.returncode == 0

        report = json.loads(Path(tmp_path / "report.json").read_text())
        totals = report["totals"]

        # Verify sums
        assert totals["statements"]["total"] == 30
        assert totals["statements"]["covered"] == 20
        assert totals["branches"]["total"] == 15
        assert totals["branches"]["covered"] == 10
        assert totals["functions"]["total"] == 8
        assert totals["functions"]["covered"] == 5

    def test_aggregation_monotonic(self, isolated_workspace, sample_coverage_data):
        """Adding more files must not decrease totals."""
        tmp_path, artifacts_dir = isolated_workspace

        # First file
        (artifacts_dir / "a.json").write_text(json.dumps(sample_coverage_data))
        result1 = run_script([str(artifacts_dir), str(tmp_path / "report1.json")])
        report1 = json.loads(Path(tmp_path / "report1.json").read_text())

        # Add second file
        (artifacts_dir / "b.json").write_text(json.dumps(sample_coverage_data))
        result2 = run_script([str(artifacts_dir), str(tmp_path / "report2.json")])
        report2 = json.loads(Path(tmp_path / "report2.json").read_text())

        assert result1.returncode == result2.returncode == 0
        for metric in ["statements", "branches", "functions"]:
            assert report2["totals"][metric]["total"] >= report1["totals"][metric]["total"]
            assert report2["totals"][metric]["covered"] >= report1["totals"][metric]["covered"]


