    def test_path_traversal_prevention(self, isolated_workspace, sample_coverage_data):
        """Script must not allow path traversal outside artifacts dir."""
        tmp_path, artifacts_dir = isolated_workspace

        # Attempt to create file with traversal in name
        malicious_name = "..%2F..%2Fetc%2Fpasswd.json"
